import {spawn} from 'node:child_process';
import {once} from 'node:events';
import {mkdirSync,writeFileSync} from 'node:fs';
import {join} from 'node:path';
import assert from 'node:assert/strict';
import Database from '/tmp/alix-srap-p4/node_modules/better-sqlite3/lib/index.js';
import {RuntimeLedger} from '/tmp/alix-srap-p4/dist/src/runtime-state/storage/runtime-ledger.js';
const root=process.argv[2];
const sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
const results=[];
for(let repeat=1;repeat<=3;repeat++){
 const dir=join(root,`crash-full-${repeat}`);mkdirSync(dir);
 const dbPath=join(dir,'runtime.db');
 const children=[];let ledger;
 try{
  for(let workerId=0;workerId<4;workerId++){
   const cfg={workerId,runId:`crash-full-${repeat}`,dbPath,mode:'sustained',seconds:30,burst:25,bursts:40,sessionK:6,thinkMs:0};
   const child=spawn(process.execPath,['scripts/benchmark-runtime-ledger-workloads.mjs','--worker',JSON.stringify(cfg)],{cwd:'/tmp/alix-srap-p4',stdio:['ignore','ignore','pipe']});
   let stderr='';child.stderr.on('data',b=>stderr+=b.toString());
   const exited=once(child,'exit');children.push({child,exited,getStderr:()=>stderr});
  }
  await sleep(1000);
  ledger=new RuntimeLedger({dbPath});
  const observed=ledger.readEvents({sinceSeq:0,limit:10000});assert.ok(observed.length>0 && observed.length<10000);
  const countBefore=observed.length;
  await sleep(500);
  for(const {child} of children) assert.equal(child.kill('SIGKILL'),true);
  const exits=await Promise.all(children.map(x=>x.exited));
  for(const [code,signal] of exits) assert.equal(signal,'SIGKILL');
  ledger.close();ledger=undefined;
  const reopened=new RuntimeLedger({dbPath});
  assert.deepEqual(reopened.readEvents({sinceSeq:0,limit:observed.length}),observed);
  const settings=reopened.durabilitySettings();reopened.close();
  const db=new Database(dbPath,{readonly:true});const countAfter=db.prepare('SELECT COUNT(*) AS n FROM runtime_events').get().n;const integrity=db.pragma('integrity_check');db.close();
  assert.ok(countAfter>=countBefore);assert.deepEqual(integrity,[{integrity_check:'ok'}]);
  const result={repeat,writerProcesses:4,signal:'SIGKILL',countBefore,countAfter,observedEventsPreserved:observed.length,settings,integrity,workerStderr:children.map(x=>x.getStderr())};
  results.push(result);writeFileSync(join(root,'crash-full-results.json'),JSON.stringify(results,null,2)+'\n');console.log(JSON.stringify(result));
 }finally{
  for(const {child} of children) if(child.exitCode===null&&child.signalCode===null)child.kill('SIGKILL');
  await Promise.allSettled(children.map(x=>x.exited));ledger?.close();
 }
}

